import { useCallback, useEffect, useMemo, useState, type ReactNode } from 'react';
import { Activity, AlertTriangle, ArrowDownLeft, ArrowUpRight, BadgeCheck, Banknote, Boxes, BriefcaseBusiness, CalendarClock, Check, ChevronDown, CircleDollarSign, ClipboardCheck, Download, FileCheck2, FileClock, FileSpreadsheet, FileText, Factory, Gauge, LockKeyhole, Mail, Package, Plus, RefreshCw, Search, ShieldAlert, ShieldCheck, Sparkles, TrendingDown, TrendingUp, Upload, Users, Wallet, X } from 'lucide-react';
import { Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import * as XLSX from 'xlsx';
import { actionRecord, api, createRecord, formatDate, formatVnd, getRecords, messageOf, statusLabel, updateRecord, type RecordRow } from './api';
import { useAuth } from './auth';
import { AddButton, Button, Card, EmptyState, Metric, PageHeader, RecordModal, SearchBox, StatusBadge, useToast, type FieldDef } from './components';
import { Link, useSearchParams } from 'react-router-dom';

type Row = RecordRow & Record<string, any>;
type Column = { key: string; label: string; format?: 'money' | 'date' | 'status' | 'classification' };
type Action = { label: string; action: string; variant?: 'primary' | 'secondary' | 'ghost' };
type ResourceProps = { entity: string; title: string; description: string; icon: ReactNode; columns: Column[]; fields: FieldDef[]; actions?: (row: Row, role: string) => Action[]; toolbar?: ReactNode; rowExtra?: (row: Row, reload: () => Promise<void>) => ReactNode; emptyDescription?: string };

const classificationNames: Record<string, string> = { BUSINESS_INCOME: 'Thu kinh doanh', BUSINESS_EXPENSE: 'Chi kinh doanh', PERSONAL: 'Cá nhân', INTERNAL_TRANSFER: 'Chuyển nội bộ', OWNER_FUNDING: 'Chủ bổ sung vốn', OWNER_DRAW: 'Chủ rút tiền', UNCLASSIFIED: 'Chưa phân loại' };
const classificationOptions = Object.entries(classificationNames).map(([value, label]) => ({ value, label }));
const directionOptions = [{ value: 'INCOME', label: 'Thu tiền' }, { value: 'EXPENSE', label: 'Chi tiền' }];
const formatCell = (row: Row, column: Column) => {
  const value = row[column.key];
  if (column.format === 'money') return formatVnd(value);
  if (column.format === 'date') return formatDate(value);
  if (column.format === 'status') return <StatusBadge status={value} />;
  if (column.format === 'classification') return <StatusBadge status={value} label={classificationNames[String(value)] || 'Chưa phân loại'} />;
  if (column.key === 'direction') return value === 'INCOME' ? <span className="text-emerald-700">Thu tiền</span> : value === 'EXPENSE' ? <span className="text-rose-700">Chi tiền</span> : 'Chuyển khoản';
  if (column.key === 'progress') return <div className="flex min-w-24 items-center gap-2"><div className="h-1.5 flex-1 overflow-hidden rounded-full bg-gray-100"><div className="h-full rounded-full bg-brand-600" style={{ width: `${Number(value || 0)}%` }} /></div><span className="text-xs text-muted">{Number(value || 0)}%</span></div>;
  return value === undefined || value === null || value === '' ? '—' : String(value);
};

function useRows(entity: string) {
  const [rows, setRows] = useState<Row[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState('');
  const reload = useCallback(async () => { setLoading(true); setError(''); try { setRows(await getRecords<Row>(entity)); } catch (reason) { setError(messageOf(reason)); } finally { setLoading(false); } }, [entity]);
  useEffect(() => { void reload(); }, [reload]);
  const hasPendingOdooSync = rows.some((row) => ['PENDING_ODOO', 'PENDING', 'PROCESSING'].includes(String(row.syncStatus || '')));
  useEffect(() => {
    if (!hasPendingOdooSync) return;
    const timer = window.setInterval(() => { void getRecords<Row>(entity).then(setRows).catch(() => undefined); }, 2500);
    return () => window.clearInterval(timer);
  }, [entity, hasPendingOdooSync]);
  return { rows, setRows, loading, error, reload };
}

function ResourcePage({ entity, title, description, icon, columns, fields, actions, toolbar, rowExtra, emptyDescription }: ResourceProps) {
  const { rows, loading, error, reload } = useRows(entity); const [searchParams] = useSearchParams(); const [search, setSearch] = useState(searchParams.get('q') || ''); const [status, setStatus] = useState(''); const [modal, setModal] = useState(false); const [editing, setEditing] = useState<Row | null>(null); const [busy, setBusy] = useState(false); const [page, setPage] = useState(1); const [sort, setSort] = useState({ key: columns[0]?.key || 'id', descending: true }); const toast = useToast(); const { user } = useAuth();
  const filtered = useMemo(() => rows.filter((row) => (!status || row.status === status) && (!search || JSON.stringify(row).toLowerCase().includes(search.toLowerCase()))), [rows, search, status]);
  const sorted = useMemo(() => [...filtered].sort((left, right) => {
    const a = left[sort.key]; const b = right[sort.key];
    const comparison = typeof a === 'number' && typeof b === 'number' ? a - b : String(a ?? '').localeCompare(String(b ?? ''), 'vi', { numeric: true, sensitivity: 'base' });
    return sort.descending ? -comparison : comparison;
  }), [filtered, sort]);
  const pageSize = 10; const pageCount = Math.max(1, Math.ceil(sorted.length / pageSize));
  const visibleRows = sorted.slice((page - 1) * pageSize, page * pageSize);
  useEffect(() => { setPage(1); }, [search, status]);
  const onCreate = async (value: Record<string, unknown>) => { setBusy(true); try { await createRecord(entity, value); setModal(false); toast('Đã lưu dữ liệu.'); await reload(); } catch (reason) { throw new Error(messageOf(reason)); } finally { setBusy(false); } };
  const onUpdate = async (value: Record<string, unknown>) => { if (!editing) return; setBusy(true); try { await updateRecord(entity, editing.id, value); setEditing(null); toast('Đã cập nhật dữ liệu.'); await reload(); } catch (reason) { throw new Error(messageOf(reason)); } finally { setBusy(false); } };
  const onCancelRecord = async (row: Row) => { const reason = window.prompt('Lý do hủy bản ghi?'); if (!reason?.trim()) return; try { await api.delete(`/${entity}/${row.id}`, { data: { reason } }); toast('Đã hủy mềm bản ghi.'); await reload(); } catch (error) { toast(messageOf(error), 'error'); } };
  const onAction = async (row: Row, action: Action) => {
    let note = '';
    if (action.action === 'reject') { note = window.prompt('Lý do từ chối báo giá?') || ''; if (!note) return; }
    if (action.action === 'lock' && !window.confirm('Khóa kỳ này? Dữ liệu sau khi khóa sẽ không thể sửa trực tiếp.')) return;
    if (action.action === 'unlock') { note = window.prompt('Nhập lý do mở khóa kỳ:') || ''; if (!note) return; }
    try { await actionRecord(entity, row.id, action.action, { note }); toast(action.action === 'simulate-code' ? 'Đã mô phỏng cấp mã. Đây không phải mã cơ quan thuế.' : 'Đã cập nhật trạng thái.'); await reload(); } catch (reason) { toast(messageOf(reason), 'error'); }
  };
  const statuses = [...new Set(rows.map((row) => String(row.status || '')).filter(Boolean))];
  const rowControls = (row: Row) => <>{rowExtra?.(row, reload)}{user?.role !== 'WORKSHOP' && row.status !== 'LOCKED' && row.status !== 'CANCELLED' && !['transactions', 'payments', 'payment-allocations', 'stock-movements', 'labor-logs', 'reconciliations'].includes(entity) && (user?.permissions?.actions === '*' || user?.permissions?.actions?.includes('update')) && <Button variant="ghost" className="px-2.5 py-1.5 text-xs" onClick={() => setEditing(row)}>Sửa</Button>}{row.status !== 'CANCELLED' && actions?.(row, user?.role || '').filter((action) => !user?.permissions || user.permissions.actions === '*' || user.permissions.actions.includes(action.action)).map((action) => <Button key={action.action} variant={action.variant || 'ghost'} className="px-2.5 py-1.5 text-xs" onClick={() => void onAction(row, action)}>{action.label}</Button>)}{user?.role === 'OWNER' && !['tax-periods', 'payment-allocations', 'labor-logs', 'reconciliations'].includes(entity) && row.status !== 'LOCKED' && row.status !== 'CANCELLED' && !(entity === 'payments' && Number(row.allocatedAmount || 0) > 0) && !(entity === 'invoices' && Number(row.paidAmount || 0) > 0) && <Button variant="danger" className="px-2.5 py-1.5 text-xs" onClick={() => void onCancelRecord(row)}>Hủy</Button>}</>;
  return <>
    <PageHeader title={title} description={description} action={<div className="flex gap-2">{toolbar}{user?.role !== 'WORKSHOP' && (user?.permissions?.actions === '*' || user?.permissions?.actions?.includes('create')) && <AddButton onClick={() => setModal(true)} label="Thêm mới" />}</div>} />
    <Card className="overflow-hidden">
      <div className="flex flex-col gap-3 border-b border-line p-4 sm:flex-row sm:items-center sm:justify-between"><div className="w-full sm:max-w-sm"><SearchBox value={search} onChange={setSearch} /></div><div className="flex items-center gap-2"><span className="hidden text-xs text-muted sm:block">Trạng thái</span><select value={status} onChange={(e) => setStatus(e.target.value)} className="rounded-xl border border-line bg-white px-3 py-2.5 text-sm text-muted outline-none focus:border-brand-500"><option value="">Tất cả trạng thái</option>{statuses.map((value) => <option key={value} value={value}>{statusLabel(value)}</option>)}</select><button onClick={() => void reload()} title="Làm mới" className="rounded-xl border border-line p-2.5 text-muted hover:bg-gray-50"><RefreshCw size={16} /></button></div></div>
      {error ? <div className="p-6 text-sm text-red-700">{error}</div> : loading ? <div className="p-14 text-center text-sm text-muted">Đang tải dữ liệu…</div> : filtered.length === 0 ? <EmptyState description={search ? 'Thử từ khóa khác hoặc xóa bộ lọc.' : emptyDescription} /> : <>
        <div className="divide-y divide-line p-3 md:hidden">{visibleRows.map((row) => <article key={row.id} className="rounded-2xl border border-line p-4"><div className="grid grid-cols-2 gap-x-3 gap-y-3">{columns.map((column) => <div key={column.key} className="min-w-0"><p className="text-[10px] font-medium uppercase tracking-wide text-muted">{column.label}</p><div className="mt-1 truncate text-sm text-ink">{formatCell(row, column)}</div></div>)}</div><div className="mt-4 flex flex-wrap justify-end gap-2 border-t border-line pt-3">{rowControls(row)}</div></article>)}</div>
        <div className="hidden overflow-x-auto md:block"><table className="w-full text-left"><thead className="bg-gray-50/80"><tr>{columns.map((column) => <th key={column.key} className="whitespace-nowrap px-5 py-3 text-[11px] font-semibold uppercase tracking-wider text-muted"><button className="inline-flex items-center gap-1 hover:text-ink" onClick={() => setSort((current) => ({ key: column.key, descending: current.key === column.key ? !current.descending : false }))}>{column.label}<span aria-hidden="true">{sort.key === column.key ? sort.descending ? '↓' : '↑' : '↕'}</span></button></th>)}<th className="px-5 py-3 text-right text-[11px] font-semibold uppercase tracking-wider text-muted">Thao tác</th></tr></thead><tbody className="divide-y divide-line">{visibleRows.map((row) => <tr key={row.id} className="transition hover:bg-gray-50/70">{columns.map((column) => <td key={column.key} className="max-w-[260px] px-5 py-4 text-sm text-ink"><div className="truncate">{formatCell(row, column)}</div></td>)}<td className="px-5 py-3"><div className="flex justify-end gap-1">{rowControls(row)}</div></td></tr>)}</tbody></table></div>
      </>}
      <div className="flex flex-col gap-3 border-t border-line px-5 py-3 text-xs text-muted sm:flex-row sm:items-center sm:justify-between"><span>{filtered.length} bản ghi · Dữ liệu lưu qua FinTax API</span>{filtered.length > pageSize && <div className="flex items-center gap-3"><span>Trang {page}/{pageCount}</span><button disabled={page <= 1} onClick={() => setPage((current) => Math.max(1, current - 1))} className="rounded-lg border border-line px-3 py-1.5 disabled:opacity-40">Trước</button><button disabled={page >= pageCount} onClick={() => setPage((current) => Math.min(pageCount, current + 1))} className="rounded-lg border border-line px-3 py-1.5 disabled:opacity-40">Tiếp</button></div>}</div>
    </Card>
    {modal && <RecordModal title={title} fields={fields} onClose={() => setModal(false)} onSubmit={onCreate} busy={busy} />}
    {editing && <RecordModal key={editing.id} title={`Sửa · ${title}`} fields={fields} initial={entity === 'cash-accounts' ? { ...editing, openingBalance: editing.openingBalance ?? editing.balance } : editing} onClose={() => setEditing(null)} onSubmit={onUpdate} busy={busy} />}
  </>;
}

export function DashboardPage() {
  const [data, setData] = useState<any>(null); const [loading, setLoading] = useState(true); const [range, setRange] = useState('30'); const toast = useToast(); const { user } = useAuth();
  const load = useCallback(async () => { setLoading(true); try { const toDate = new Date(); const fromDate = new Date(); fromDate.setDate(fromDate.getDate() - Number(range)); const { data: result } = await api.get('/dashboard', { params: { from: fromDate.toISOString().slice(0, 10), to: toDate.toISOString().slice(0, 10) } }); setData(result); } catch (error) { toast(messageOf(error), 'error'); } finally { setLoading(false); } }, [range]);
  useEffect(() => { void load(); }, [load]);
  const metrics = data?.metrics || {};
  return <>
    <PageHeader eyebrow={`TỔNG QUAN · ${data?.branches?.[0]?.name?.toLocaleUpperCase('vi') || 'FINTAX AUTOMATION'}`} title={`Xin chào, ${user?.name?.split(' ')[0] || 'bạn'}`} description="Theo dõi dòng tiền và hoạt động xưởng của bạn tại một nơi." action={<select value={range} onChange={(e) => setRange(e.target.value)} className="rounded-xl border border-line bg-white px-3.5 py-2.5 text-sm outline-none"><option value="7">7 ngày qua</option><option value="30">30 ngày qua</option><option value="90">90 ngày qua</option></select>} />
    <div className="mb-6 flex items-start gap-3 rounded-2xl border border-amber-200 bg-amber-50/70 px-4 py-3.5"><span className="mt-0.5 text-amber-700"><ShieldAlert size={17} /></span><div><p className="text-sm font-medium text-amber-900">Chế độ trình diễn · Dữ liệu mẫu</p><p className="mt-0.5 text-xs leading-5 text-amber-800">Mã hóa đơn và quy tắc thuế ở đây chỉ phục vụ mô phỏng, chưa kết nối cơ quan thuế hoặc thay thế tư vấn chuyên môn.</p></div><span className="ml-auto shrink-0 rounded-full bg-white/80 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wide text-amber-800">DEMO</span></div>
    {loading && !data ? <div className="py-20 text-center text-sm text-muted">Đang tải bảng điều hành…</div> : <>
      <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Link to="/transactions?q=BUSINESS_INCOME" className="rounded-2xl outline-none transition hover:-translate-y-0.5 focus-visible:ring-2 focus-visible:ring-brand-500"><Metric label="Thu kinh doanh" value={metrics.revenue || 0} caption="Theo giao dịch đã phân loại" icon={<ArrowDownLeft size={19} />} tone="green" /></Link><Link to="/transactions?q=BUSINESS_EXPENSE" className="rounded-2xl outline-none transition hover:-translate-y-0.5 focus-visible:ring-2 focus-visible:ring-brand-500"><Metric label="Chi kinh doanh" value={metrics.expenses || 0} caption="Không gồm dòng tiền cá nhân" icon={<ArrowUpRight size={19} />} tone="amber" /></Link><Link to="/payments" className="rounded-2xl outline-none transition hover:-translate-y-0.5 focus-visible:ring-2 focus-visible:ring-brand-500"><Metric label="Công nợ phải thu" value={metrics.receivable || 0} caption="Từ hồ sơ khách hàng" icon={<CircleDollarSign size={19} />} tone="blue" /></Link><Link to="/transactions" className="rounded-2xl outline-none transition hover:-translate-y-0.5 focus-visible:ring-2 focus-visible:ring-brand-500"><Metric label="Số dư các quỹ" value={metrics.balance || 0} caption="Tiền mặt và tài khoản" icon={<Wallet size={19} />} tone="brand" /></Link></div>
      <Link to="/settings" className="mt-4 flex items-center gap-3 rounded-xl border border-line bg-white px-4 py-3 text-xs transition hover:border-brand-100 hover:bg-brand-50/30"><span className={`h-2 w-2 rounded-full ${data?.integrations?.odoo?.connected ? 'bg-emerald-500' : 'bg-amber-500'}`} /><span className="font-medium">Odoo: {data?.integrations?.odoo?.label || 'Đang kiểm tra'}</span><span className="text-muted">· {data?.integrations?.pendingOdoo || 0} bản ghi đang chờ hoặc cần mapping</span><span className="ml-auto text-brand-700">Chi tiết tích hợp →</span></Link>
      <div className="mt-5 grid gap-5 xl:grid-cols-[1.65fr_1fr]"><Card className="p-5 sm:p-6"><div className="mb-5 flex items-start justify-between"><div><h2 className="font-semibold">Dòng tiền hoạt động</h2><p className="mt-1 text-xs text-muted">Thu và chi ghi nhận theo ngày</p></div><span className="rounded-lg bg-gray-50 px-2.5 py-1.5 text-[11px] text-muted">VND</span></div><div className="h-[270px]">{data?.trend?.length ? <ResponsiveContainer width="100%" height="100%"><BarChart data={data.trend} barGap={5}><CartesianGrid vertical={false} stroke="#efeff0" /><XAxis dataKey="date" tickFormatter={(value) => new Intl.DateTimeFormat('vi-VN', { day: '2-digit', month: '2-digit' }).format(new Date(value))} axisLine={false} tickLine={false} tick={{ fontSize: 11, fill: '#878991' }} /><YAxis tickFormatter={(value) => `${Math.round(value / 1000000)}tr`} axisLine={false} tickLine={false} tick={{ fontSize: 11, fill: '#878991' }} width={42} /><Tooltip formatter={(value) => formatVnd(value)} labelFormatter={(value) => formatDate(value)} contentStyle={{ border: '1px solid #e9e9eb', borderRadius: 12, boxShadow: '0 8px 25px rgba(0,0,0,.08)' }} /><Bar dataKey="thu" name="Thu vào" fill="#159a74" radius={[5, 5, 0, 0]} /><Bar dataKey="chi" name="Chi ra" fill="#c23b36" radius={[5, 5, 0, 0]} /></BarChart></ResponsiveContainer> : <EmptyState title="Chưa có giao dịch trong kỳ" />}</div><div className="mt-3 flex items-center gap-5 text-xs text-muted"><span className="flex items-center gap-2"><i className="h-2 w-2 rounded-full bg-emerald-600" />Thu vào</span><span className="flex items-center gap-2"><i className="h-2 w-2 rounded-full bg-brand-600" />Chi ra</span></div></Card>
        <Card className="p-5 sm:p-6"><div className="mb-4 flex items-center justify-between"><div><h2 className="font-semibold">Việc cần chú ý</h2><p className="mt-1 text-xs text-muted">{data?.alerts?.length || 0} nội dung đang chờ xử lý</p></div><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-amber-50 text-amber-700"><AlertTriangle size={18} /></span></div><div className="space-y-1">{data?.alerts?.length ? data.alerts.map((item: Row) => <div key={item.id} className="flex gap-3 border-b border-line py-3.5 last:border-0"><span className={`mt-1 h-2 w-2 shrink-0 rounded-full ${item.type === 'HIGH' ? 'bg-red-500' : item.type === 'MEDIUM' ? 'bg-amber-500' : 'bg-blue-500'}`} /><div className="min-w-0"><p className="text-sm font-medium">{item.title}</p><p className="mt-1 line-clamp-2 text-xs leading-5 text-muted">{item.description}</p><p className="mt-1.5 text-[10px] uppercase tracking-wide text-gray-400">{item.reference} · {formatDate(item.createdAt)}</p></div></div>) : <EmptyState title="Mọi thứ đang ổn" description="Chưa có cảnh báo cần xử lý." />}</div></Card></div>
      <div className="mt-5 grid gap-5 xl:grid-cols-[1.65fr_1fr]"><Card className="overflow-hidden"><div className="flex items-center justify-between border-b border-line px-5 py-4"><div><h2 className="font-semibold">Giao dịch gần đây</h2><p className="mt-1 text-xs text-muted">Dữ liệu thu chi mới nhất</p></div><a href="/transactions" className="text-xs font-medium text-brand-700 hover:underline">Xem sổ quỹ</a></div><div className="divide-y divide-line">{data?.recentTransactions?.slice(0, 5).map((item: Row) => <div key={item.id} className="flex items-center gap-3 px-5 py-3.5"><span className={`flex h-9 w-9 items-center justify-center rounded-xl ${item.direction === 'INCOME' ? 'bg-emerald-50 text-emerald-700' : item.direction === 'EXPENSE' ? 'bg-brand-50 text-brand-700' : 'bg-gray-100 text-gray-600'}`}>{item.direction === 'INCOME' ? <ArrowDownLeft size={17} /> : item.direction === 'EXPENSE' ? <ArrowUpRight size={17} /> : <RefreshCw size={16} />}</span><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium">{item.description}</p><p className="mt-0.5 truncate text-xs text-muted">{item.counterparty || item.accountName} · {formatDate(item.date)}</p></div><div className="text-right"><p className={`text-sm font-semibold ${item.direction === 'INCOME' ? 'text-emerald-700' : 'text-ink'}`}>{item.direction === 'INCOME' ? '+' : item.direction === 'EXPENSE' ? '−' : ''}{formatVnd(item.amount)}</p><p className="mt-0.5 text-[10px] text-muted">{classificationNames[item.classification] || 'Chuyển nội bộ'}</p></div></div>)}</div></Card>
        <Card className="p-5"><div className="mb-4 flex items-center justify-between"><div><h2 className="font-semibold">Tiến độ xưởng</h2><p className="mt-1 text-xs text-muted">Lệnh đang sản xuất</p></div><Factory size={18} className="text-brand-600" /></div><div className="space-y-4">{data?.production?.map((job: Row) => <div key={job.id}><div className="flex justify-between gap-3"><div className="min-w-0"><p className="truncate text-sm font-medium">{job.productName}</p><p className="mt-0.5 text-xs text-muted">{job.code} · {job.customerName}</p></div><span className="shrink-0 text-xs font-semibold">{job.progress}%</span></div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-gray-100"><div className="h-full rounded-full bg-brand-600" style={{ width: `${job.progress}%` }} /></div></div>)}</div><a href="/workshop" className="mt-5 inline-flex items-center gap-1 text-xs font-medium text-brand-700 hover:underline">Mở Workshop <ChevronDown size={14} className="-rotate-90" /></a></Card></div>
    </>}
  </>;
}

export function TransactionsPage() {
  const { user } = useAuth();
  const canCreate = !user?.permissions || user.permissions.actions === '*' || user.permissions.actions.includes('create');
  const canClassify = !user?.permissions || user.permissions.actions === '*' || user.permissions.actions.includes('classify');
  const [preview, setPreview] = useState<any>(null); const [file, setFile] = useState<File | null>(null); const [importBusy, setImportBusy] = useState(false); const [transferModal, setTransferModal] = useState(false); const [transferBusy, setTransferBusy] = useState(false); const [importAccountId, setImportAccountId] = useState(''); const [includeDuplicates, setIncludeDuplicates] = useState(false); const accounts = useRows('cash-accounts'); const toast = useToast();
  const businessAccounts = accounts.rows.filter((account) => account.ownerScope !== 'PERSONAL');
  const accountOptions = accounts.rows.map((account) => ({ value: account.id, label: `${account.name} · ${formatVnd(account.balance)}` }));
  useEffect(() => { if (!importAccountId && businessAccounts.length) setImportAccountId(businessAccounts[0].id); }, [businessAccounts, importAccountId]);
  const submitImport = async () => {
    if (!file) { toast('Chọn file CSV hoặc Excel trước.', 'info'); return; }
    const form = new FormData(); form.append('file', file); setImportBusy(true);
    try { const { data } = await api.post('/import/transactions/preview', form); setPreview(data); }
    catch (error) { toast(messageOf(error), 'error'); }
    finally { setImportBusy(false); }
  };
  const commitImport = async () => {
    setImportBusy(true);
    if (!importAccountId) { toast('Chọn tài khoản sẽ nhận các giao dịch sao kê.', 'info'); return; }
    try { const { data } = await api.post(`/import/transactions/${preview.importId}/commit`, { accountId: importAccountId, includeDuplicates }); toast(`Đã nhập ${data.createdCount} giao dịch; bỏ qua ${data.skippedDuplicates} dòng trùng và ${data.skippedInvalid} dòng lỗi.`); setPreview(null); setFile(null); window.location.reload(); }
    catch (error) { toast(messageOf(error), 'error'); }
    finally { setImportBusy(false); }
  };
  const transferFields: FieldDef[] = [{ name: 'date', label: 'Ngày chuyển', type: 'date', required: true }, { name: 'fromAccountId', label: 'Từ tài khoản', type: 'select', required: true, options: accountOptions }, { name: 'toAccountId', label: 'Đến tài khoản', type: 'select', required: true, options: accountOptions }, { name: 'amount', label: 'Số tiền (₫)', type: 'number', required: true, min: 1 }, { name: 'note', label: 'Nội dung', placeholder: 'Chuyển tiền nội bộ' }];
  const transferMoney = async (value: Record<string, unknown>) => { setTransferBusy(true); try { if (value.fromAccountId === value.toAccountId) throw new Error('Hãy chọn hai tài khoản khác nhau.'); await api.post('/transfers', value); toast('Đã ghi nhận cặp chuyển tiền nội bộ cân bằng.'); setTransferModal(false); window.location.reload(); } catch (error) { throw new Error(messageOf(error)); } finally { setTransferBusy(false); } };
  const toolbar = <>{canCreate && <><Button variant="secondary" onClick={() => setTransferModal(true)}><RefreshCw size={15} />Chuyển nội bộ</Button><label className="inline-flex cursor-pointer items-center gap-2 rounded-xl border border-line bg-white px-3.5 py-2.5 text-sm font-medium text-ink hover:bg-gray-50"><Upload size={15} />Import sao kê<input type="file" accept=".csv,.xlsx,.xls" className="hidden" onChange={(e) => setFile(e.target.files?.[0] || null)} /></label></>}</>;
  return <><ResourcePage entity="transactions" title="Sổ quỹ & dòng tiền" description="Thu chi, sao kê và phân loại riêng dòng tiền kinh doanh với cá nhân." icon={<Wallet size={18} />} columns={[{ key: 'date', label: 'Ngày', format: 'date' }, { key: 'description', label: 'Nội dung' }, { key: 'counterparty', label: 'Đối tượng' }, { key: 'accountName', label: 'Tài khoản' }, { key: 'direction', label: 'Loại' }, { key: 'amount', label: 'Số tiền', format: 'money' }, { key: 'classification', label: 'Phân loại', format: 'classification' }]} fields={[{ name: 'date', label: 'Ngày giao dịch', type: 'date', required: true }, { name: 'description', label: 'Nội dung', required: true }, { name: 'counterparty', label: 'Đối tượng' }, { name: 'amount', label: 'Số tiền (₫)', type: 'number', required: true, min: 1 }, { name: 'direction', label: 'Loại giao dịch', type: 'select', required: true, options: directionOptions }, { name: 'classification', label: 'Nhóm phân loại', type: 'select', required: true, options: classificationOptions }, { name: 'accountId', label: 'Tài khoản tiền', type: 'select', required: true, options: accountOptions, wide: true }, { name: 'category', label: 'Danh mục' }, { name: 'descriptionNote', label: 'Ghi chú', type: 'textarea', wide: true }]} toolbar={toolbar} actions={(row, role) => role === 'WORKSHOP' ? [] : [{ label: row.classification === 'UNCLASSIFIED' ? 'Phân loại' : 'Sửa nhóm', action: 'classify' }]} rowExtra={(row, reload) => canClassify ? <select aria-label="Phân loại giao dịch" title="Phân loại nhanh" value={row.classification || 'UNCLASSIFIED'} onChange={async (event) => { try { await actionRecord('transactions', row.id, 'classify', { classification: event.target.value }); toast('Đã cập nhật phân loại.'); await reload(); } catch (error) { toast(messageOf(error), 'error'); } }} className="max-w-36 rounded-lg border border-line bg-white px-2 py-1.5 text-[11px] text-muted"><option value="UNCLASSIFIED">Chưa phân loại</option>{classificationOptions.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}</select> : null} />
    {file && <div className="fixed bottom-5 left-5 z-40 flex items-center gap-3 rounded-2xl border border-line bg-white p-3 shadow-xl"><FileSpreadsheet size={18} className="text-emerald-700" /><div className="max-w-48 truncate text-xs">{file.name}</div><Button onClick={() => void submitImport()} disabled={importBusy}>{importBusy ? 'Đang đọc…' : 'Xem trước'}</Button><button onClick={() => setFile(null)} className="text-muted"><X size={16} /></button></div>}
    {preview && <div className="fixed inset-0 z-50 flex items-end justify-center bg-ink/40 p-0 backdrop-blur-sm sm:items-center sm:p-5"><div className="max-h-[90vh] w-full max-w-4xl overflow-hidden rounded-t-3xl bg-white shadow-2xl sm:rounded-3xl"><div className="flex items-center justify-between border-b border-line p-5"><div><p className="text-xs font-semibold uppercase tracking-wider text-brand-600">Kiểm tra trước khi nhập</p><h2 className="mt-1 font-semibold">{preview.fileName}</h2><p className="mt-1 text-xs text-muted">{preview.total} dòng · {preview.duplicateCount} trùng · {preview.errorCount} dòng lỗi</p></div><button onClick={() => setPreview(null)}><X size={20} /></button></div><div className="max-h-[55vh] overflow-auto"><table className="w-full min-w-[760px] text-left text-xs"><thead className="sticky top-0 bg-gray-50"><tr>{['Dòng', 'Ngày', 'Nội dung', 'Số tiền', 'Loại', 'Phân loại gợi ý', 'Kết quả'].map((name) => <th key={name} className="px-4 py-3 font-semibold text-muted">{name}</th>)}</tr></thead><tbody className="divide-y divide-line">{preview.rows.map((row: any) => <tr key={row.rowNumber} className={row.duplicate || row.errors.length ? 'bg-amber-50/50' : ''}><td className="px-4 py-3">{row.rowNumber}</td><td className="px-4 py-3">{row.date || '—'}</td><td className="max-w-60 truncate px-4 py-3">{row.description || '—'}</td><td className="px-4 py-3">{formatVnd(row.amount)}</td><td className="px-4 py-3">{row.direction === 'INCOME' ? 'Thu' : row.direction === 'EXPENSE' ? 'Chi' : '—'}</td><td className="px-4 py-3">{classificationNames[row.classification] || 'Chờ rà soát'}{row.classificationSource === 'RULE' && <span className="mt-1 block text-[10px] text-emerald-700">{row.classificationReason} · {row.classificationConfidence}%</span>}</td><td className="px-4 py-3 text-amber-800">{row.duplicate ? 'Có thể trùng' : row.errors.join(', ') || 'Sẵn sàng nhập'}</td></tr>)}</tbody></table></div><div className="flex flex-col gap-3 border-t border-line p-4 sm:flex-row sm:items-center"><label className="flex-1 text-xs text-muted">Tài khoản nhận sao kê<select value={importAccountId} onChange={(event) => setImportAccountId(event.target.value)} className="mt-1.5 block w-full max-w-sm rounded-xl border border-line bg-white px-3 py-2.5 text-sm"><option value="">Chọn tài khoản</option>{accountOptions.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}</select></label><label className="flex items-center gap-2 text-xs text-muted"><input type="checkbox" checked={includeDuplicates} onChange={(event) => setIncludeDuplicates(event.target.checked)} />Vẫn nhập dòng bị đánh dấu trùng</label><Button variant="secondary" onClick={() => setPreview(null)}>Hủy</Button><Button onClick={() => void commitImport()} disabled={importBusy || !importAccountId}>{importBusy ? 'Đang nhập…' : 'Nhập dòng hợp lệ'}</Button></div></div></div>}
    {transferModal && <RecordModal title="Chuyển tiền nội bộ" fields={transferFields} onClose={() => setTransferModal(false)} onSubmit={transferMoney} busy={transferBusy} />}
  </>;
}

const quoteActions = (row: Row, role: string): Action[] => {
  if (role === 'OWNER' && row.status === 'PENDING_APPROVAL') return [{ label: 'Duyệt', action: 'approve', variant: 'primary' }, { label: 'Từ chối', action: 'reject' }];
  if (role === 'ACCOUNTANT' && row.status === 'DRAFT') return [{ label: 'Gửi duyệt', action: 'submit-for-approval', variant: 'primary' }];
  if (['OWNER', 'ACCOUNTANT'].includes(role) && row.status === 'APPROVED') return [{ label: 'Đánh dấu đã gửi khách', action: 'mark-sent', variant: 'primary' }];
  if (['OWNER', 'ACCOUNTANT'].includes(role) && row.status === 'SENT') return [{ label: 'Khách đã chấp nhận', action: 'accept', variant: 'primary' }];
  if (['OWNER', 'ACCOUNTANT'].includes(role) && row.status === 'ACCEPTED' && !row.productionOrderId) return [{ label: 'Tạo lệnh sản xuất', action: 'create-production', variant: 'primary' }];
  return [];
};
const quoteFields: FieldDef[] = [
  { name: 'code', label: 'Mã báo giá', required: true, placeholder: 'BG-2026-020' }, { name: 'customerName', label: 'Khách hàng', required: true },
  { name: 'title', label: 'Sản phẩm / dịch vụ', required: true }, { name: 'date', label: 'Ngày lập', type: 'date', required: true },
  { name: 'validUntil', label: 'Hiệu lực đến', type: 'date' }, { name: 'quantity', label: 'Số lượng', type: 'number', min: 0.01 },
  { name: 'materialCost', label: 'Chi phí vật tư (₫)', type: 'number', min: 0 }, { name: 'laborHours', label: 'Giờ công', type: 'number', min: 0 },
  { name: 'laborRate', label: 'Chi phí/giờ công (₫)', type: 'number', min: 0 }, { name: 'machineCost', label: 'Điện/máy phân bổ (₫)', type: 'number', min: 0 },
  { name: 'wasteRate', label: 'Hao hụt dự kiến (%)', type: 'number', min: 0 }, { name: 'marginRate', label: 'Biên lợi nhuận mục tiêu (%)', type: 'number', min: 0 },
  { name: 'unitPrice', label: 'Đơn giá tùy chỉnh (₫, bỏ trống để gợi ý)', type: 'number', min: 0 }, { name: 'taxAmount', label: 'Tiền thuế nhập theo hồ sơ đã rà soát (₫)', type: 'number', min: 0 },
  { name: 'terms', label: 'Điều khoản / ghi chú', type: 'textarea', wide: true },
  { name: 'status', label: 'Trạng thái', type: 'select', options: [{ value: 'DRAFT', label: 'Bản nháp' }, { value: 'PENDING_APPROVAL', label: 'Chờ duyệt' }] },
];
const htmlText = (value: unknown) => String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char] || char));
function printQuotation(row: Row) {
  const printWindow = window.open('', '_blank');
  if (!printWindow) return false;
  const items = Array.isArray(row.items) ? row.items : [{ name: row.title, quantity: row.quantity, unitPrice: row.unitPrice, amount: row.subtotal }];
  const lineRows = items.map((item: Row) => `<tr><td>${htmlText(item.name || row.title)}</td><td>${htmlText(item.quantity ?? row.quantity ?? '')}</td><td>${htmlText(item.unit || '')}</td><td class="num">${formatVnd(item.unitPrice ?? row.unitPrice ?? 0)}</td><td class="num">${formatVnd(item.amount ?? row.subtotal ?? 0)}</td></tr>`).join('');
  printWindow.document.write(`<!doctype html><html lang="vi"><head><meta charset="utf-8"><title>${htmlText(row.code)} · Báo giá</title><style>@page{size:A4;margin:18mm}*{box-sizing:border-box}body{font:14px Arial,sans-serif;color:#252326;max-width:760px;margin:0 auto;padding:20px}header{display:flex;align-items:center;justify-content:space-between;border-bottom:2px solid #9f201d;padding-bottom:18px}header img{width:210px;height:62px;object-fit:contain;object-position:left center}h1{font-size:24px;margin:28px 0 8px;color:#7d1d1b}.muted{color:#707078;font-size:12px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:22px 0}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{padding:10px 8px;border-bottom:1px solid #e8e6e6;text-align:left}th{background:#f7f5f4;font-size:11px;text-transform:uppercase}.num{text-align:right;white-space:nowrap}.totals{width:300px;margin:18px 0 0 auto}.totals div{display:flex;justify-content:space-between;padding:6px 0}.grand{border-top:1px solid #aaa;font-weight:bold;font-size:17px}.terms{margin-top:32px;padding-top:16px;border-top:1px solid #e8e6e6;white-space:pre-wrap}.sign{display:flex;justify-content:space-between;margin-top:64px;text-align:center}.sign div{width:42%}@media print{body{padding:0}}</style></head><body><header><img src="${location.origin}/logo.png" alt="DichVuThue FinTax"><span class="muted">BẢN BÁO GIÁ</span></header><h1>Báo giá ${htmlText(row.code)}</h1><div class="grid"><div><b>Khách hàng</b><br>${htmlText(row.customerName)}<br>${htmlText(row.customerAddress || '')}</div><div><b>Ngày lập</b> ${formatDate(row.date)}<br><b>Hiệu lực đến</b> ${formatDate(row.validUntil)}</div></div><table><thead><tr><th>Sản phẩm / dịch vụ</th><th>SL</th><th>ĐVT</th><th class="num">Đơn giá</th><th class="num">Thành tiền</th></tr></thead><tbody>${lineRows}</tbody></table><div class="totals"><div><span>Tiền hàng</span><b>${formatVnd(row.subtotal || 0)}</b></div><div><span>Thuế theo thông tin nhập</span><b>${formatVnd(row.taxAmount || 0)}</b></div><div class="grand"><span>Tổng cộng</span><b>${formatVnd(row.total || 0)}</b></div></div>${row.terms ? `<div class="terms"><b>Điều khoản / ghi chú</b><br>${htmlText(row.terms)}</div>` : ''}<div class="sign"><div>ĐẠI DIỆN KHÁCH HÀNG</div><div>ĐẠI DIỆN XƯỞNG</div></div><script>window.onload=()=>setTimeout(()=>window.print(),250)</script></body></html>`);
  printWindow.document.close();
  return true;
}
function exportQuotation(row: Row) {
  const book = XLSX.utils.book_new();
  const summary = XLSX.utils.json_to_sheet([{ 'Mã báo giá': row.code, 'Khách hàng': row.customerName, 'Sản phẩm / dịch vụ': row.title, 'Ngày lập': row.date, 'Hiệu lực đến': row.validUntil, 'Số lượng': row.quantity, 'Giá vốn dự kiến': row.costEstimate, 'Đơn giá đề xuất': row.suggestedUnitPrice ?? row.unitPrice, 'Tiền hàng': row.subtotal, 'Thuế nhập theo hồ sơ': row.taxAmount, 'Tổng tiền': row.total, 'Trạng thái': statusLabel(row.status), 'Phiên bản': row.version || 1 }]);
  XLSX.utils.book_append_sheet(book, summary, 'Báo giá');
  const items = Array.isArray(row.items) ? row.items : [{ name: row.title, quantity: row.quantity, unitPrice: row.unitPrice, amount: row.subtotal }];
  XLSX.utils.book_append_sheet(book, XLSX.utils.json_to_sheet(items.map((item: Row) => ({ 'Sản phẩm / dịch vụ': item.name || row.title, 'Số lượng': item.quantity ?? row.quantity, 'Đơn vị': item.unit || '', 'Đơn giá': item.unitPrice ?? row.unitPrice, 'Thành tiền': item.amount ?? row.subtotal }))), 'Chi tiết');
  XLSX.utils.book_append_sheet(book, XLSX.utils.aoa_to_sheet([['CẤU THÀNH GIÁ DỰ KIẾN'], ['Vật tư', row.materialCost || 0], ['Nhân công', row.laborCost || 0], ['Điện/máy', row.machineCost || 0], ['Hao hụt', row.wasteRate || 0], ['Giá vốn ước tính', row.costEstimate || 0], ['Biên mục tiêu', row.marginRate || 0]]), 'Cấu thành giá');
  XLSX.writeFile(book, `${row.code || 'bao-gia'}.xlsx`);
}
export function QuotationsPage() {
  const toast = useToast();
  return <><div className="mb-4 rounded-2xl border border-amber-200 bg-amber-50/70 px-4 py-3 text-xs leading-5 text-amber-900">Thuế trong báo giá chỉ lấy từ thông tin người dùng nhập và quy tắc nội bộ đã rà soát. Hệ thống không tự xác nhận mức thuế hợp pháp.</div><ResourcePage entity="quotations" title="Báo giá & định mức" description="Tính giá thành theo vật tư, giờ công, máy móc và hao hụt; quản lý phiên bản và luồng duyệt." icon={<FileText size={18} />} columns={[{ key: 'code', label: 'Mã báo giá' }, { key: 'customerName', label: 'Khách hàng' }, { key: 'title', label: 'Sản phẩm / dịch vụ' }, { key: 'date', label: 'Ngày lập', format: 'date' }, { key: 'costEstimate', label: 'Giá vốn dự kiến', format: 'money' }, { key: 'total', label: 'Tổng báo giá', format: 'money' }, { key: 'status', label: 'Trạng thái', format: 'status' }]} fields={quoteFields} actions={quoteActions} rowExtra={(row) => <>{row.odooUrl ? <a href={row.odooUrl} target="_blank" rel="noreferrer" className="rounded-lg px-2 py-1 text-xs font-medium text-brand-700 hover:bg-brand-50">Mở Sales ↗</a> : row.syncStatus === 'PENDING_ODOO' ? <span className="px-2 py-1 text-xs text-muted">Đang đồng bộ Odoo…</span> : null}<Button variant="ghost" className="px-2 py-1 text-xs" onClick={() => exportQuotation(row)}>Excel</Button><Button variant="secondary" className="px-2 py-1 text-xs" onClick={() => { if (!printQuotation(row)) toast('Trình duyệt đã chặn cửa sổ in. Hãy cho phép cửa sổ bật lên rồi thử lại.', 'error'); }}>PDF / In</Button></>} /> </>;
}

const productionActions = (row: Row): Action[] => row.status === 'COMPLETED' ? [] : row.status === 'IN_PROGRESS' ? [{ label: 'Hoàn tất', action: 'complete', variant: 'primary' }] : [{ label: 'Bắt đầu', action: 'start', variant: 'primary' }];
export function WorkshopPage() {
  const { user } = useAuth(); const materials = useRows('materials'); const toast = useToast(); const [selectedJob, setSelectedJob] = useState<Row | null>(null); const [laborJob, setLaborJob] = useState<Row | null>(null); const [progressJob, setProgressJob] = useState<Row | null>(null); const [refreshJobs, setRefreshJobs] = useState<(() => Promise<void>) | null>(null); const [busy, setBusy] = useState(false);
  const movementFields: FieldDef[] = [{ name: 'materialId', label: 'Vật tư', type: 'select', required: true, wide: true, options: materials.rows.map((item) => ({ value: item.id, label: `${item.name} · tồn ${item.stock} ${item.unit || ''}` })) }, { name: 'type', label: 'Loại phiếu', type: 'select', required: true, options: [{ value: 'ISSUE', label: 'Xuất dùng cho sản xuất' }, { value: 'RETURN', label: 'Trả vật tư về kho' }, { value: 'WASTE', label: 'Ghi nhận hao hụt/hỏng' }] }, { name: 'quantity', label: 'Số lượng', type: 'number', required: true, min: 0.01 }, { name: 'date', label: 'Ngày', type: 'date', required: true }, { name: 'attachmentName', label: 'Ảnh phiếu / chứng từ', type: 'file', wide: true }, { name: 'note', label: 'Ghi chú', type: 'textarea', wide: true }];
  const laborFields: FieldDef[] = [{ name: 'hours', label: 'Số giờ công', type: 'number', required: true, min: 0.1 }, { name: 'stage', label: 'Công đoạn', required: true }, { name: 'date', label: 'Ngày làm', type: 'date', required: true }, { name: 'note', label: 'Ghi chú công việc', type: 'textarea', wide: true }];
  const progressFields: FieldDef[] = [{ name: 'progress', label: 'Tiến độ (%)', type: 'number', required: true, min: 0, max: 100 }, { name: 'stage', label: 'Công đoạn hiện tại', required: true, wide: true }];
  const saveMovement = async (value: Record<string, unknown>) => {
    const material = materials.rows.find((row) => row.id === value.materialId);
    if (!material || !selectedJob) throw new Error('Không tìm thấy lệnh sản xuất hoặc vật tư.');
    setBusy(true);
    try { await createRecord('stock-movements', { ...value, code: `PX-${Date.now().toString().slice(-6)}`, materialName: material.name, productionOrderId: selectedJob.id, status: 'CONFIRMED' }); toast('Đã ghi nhận luân chuyển vật tư và cập nhật tồn kho.'); setSelectedJob(null); await Promise.all([materials.reload(), refreshJobs?.() || Promise.resolve()]); }
    catch (error) { throw new Error(messageOf(error)); }
    finally { setBusy(false); }
  };
  const saveLabor = async (value: Record<string, unknown>) => {
    if (!laborJob) throw new Error('Chọn lệnh sản xuất trước khi ghi giờ công.');
    setBusy(true);
    try { await createRecord('labor-logs', { ...value, productionOrderId: laborJob.id }); toast('Đã ghi giờ công vào lệnh sản xuất.'); setLaborJob(null); await refreshJobs?.(); }
    catch (error) { throw new Error(messageOf(error)); }
    finally { setBusy(false); }
  };
  const saveProgress = async (value: Record<string, unknown>) => {
    if (!progressJob) throw new Error('Chọn lệnh sản xuất trước khi cập nhật tiến độ.');
    setBusy(true);
    try { await actionRecord('production-orders', progressJob.id, 'progress', value); toast('Đã cập nhật công đoạn và tiến độ.'); setProgressJob(null); await refreshJobs?.(); }
    catch (error) { throw new Error(messageOf(error)); }
    finally { setBusy(false); }
  };
  return <><div className="mb-5 rounded-2xl border border-brand-100 bg-brand-50/70 p-4"><div className="flex items-start gap-3"><span className="rounded-xl bg-white p-2 text-brand-700"><Factory size={18} /></span><div><p className="text-sm font-semibold text-brand-900">Workshop · {user?.role === 'WORKSHOP' ? 'Không gian dành cho bạn' : 'Theo dõi tiến độ xưởng'}</p><p className="mt-1 text-xs leading-5 text-brand-800">Nhân viên xưởng chỉ xem lệnh được phân công, cập nhật công đoạn và ghi nhận vật tư/giờ công.</p></div></div></div><ResourcePage entity="production-orders" title="Lệnh sản xuất" description="Theo dõi lô sản xuất, công đoạn, tiến độ và ngày cần hoàn thành." icon={<Factory size={18} />} columns={[{ key: 'code', label: 'Mã lệnh' }, { key: 'productName', label: 'Sản phẩm' }, { key: 'customerName', label: 'Khách hàng' }, { key: 'stage', label: 'Công đoạn' }, { key: 'progress', label: 'Tiến độ' }, { key: 'dueDate', label: 'Hạn hoàn thành', format: 'date' }, { key: 'status', label: 'Trạng thái', format: 'status' }]} fields={[{ name: 'code', label: 'Mã lệnh', required: true }, { name: 'productName', label: 'Sản phẩm', required: true }, { name: 'customerName', label: 'Khách hàng' }, { name: 'quantity', label: 'Số lượng', type: 'number', min: 0 }, { name: 'assignedTo', label: 'Người phụ trách' }, { name: 'stage', label: 'Công đoạn' }, { name: 'dueDate', label: 'Ngày cần xong', type: 'date' }, { name: 'status', label: 'Trạng thái', type: 'select', options: [{ value: 'IN_PROGRESS', label: 'Đang thực hiện' }, { value: 'DRAFT', label: 'Mới tạo' }] }]} actions={productionActions} rowExtra={(row, reload) => <><Button variant="secondary" className="px-2.5 py-1.5 text-xs" onClick={() => { setSelectedJob(row); setRefreshJobs(() => reload); }}>Ghi vật tư</Button><Button variant="ghost" className="px-2.5 py-1.5 text-xs" onClick={() => { setLaborJob(row); setRefreshJobs(() => reload); }}>Giờ công</Button><Button variant="ghost" className="px-2.5 py-1.5 text-xs" onClick={() => { setProgressJob(row); setRefreshJobs(() => reload); }}>Tiến độ</Button></>} emptyDescription="Tạo lệnh sản xuất đầu tiên hoặc nhận phân công từ chủ xưởng." />{selectedJob && <RecordModal title={`Phiếu vật tư · ${selectedJob.code}`} fields={movementFields} onClose={() => setSelectedJob(null)} onSubmit={saveMovement} busy={busy} />}{laborJob && <RecordModal title={`Ghi giờ công · ${laborJob.code}`} fields={laborFields} onClose={() => setLaborJob(null)} onSubmit={saveLabor} busy={busy} />}{progressJob && <RecordModal title={`Cập nhật tiến độ · ${progressJob.code}`} fields={progressFields} onClose={() => setProgressJob(null)} onSubmit={saveProgress} busy={busy} />}</>;
}

export function InvoicesPage() {
  return <><div className="mb-4 flex items-start gap-3 rounded-2xl border border-blue-200 bg-blue-50/70 px-4 py-3"><InfoIcon /><p className="text-xs leading-5 text-blue-900"><strong>Môi trường giả lập.</strong> “Mô phỏng xin mã” không gửi dữ liệu đến cơ quan thuế và mã trả về không có giá trị pháp lý. Tệp đính kèm cần rà soát thủ công (OCR chưa cấu hình).</p></div><ResourcePage entity="invoices" title="Hóa đơn điện tử" description="Lưu hóa đơn đầu vào/đầu ra, rà soát dữ liệu và mô phỏng luồng cấp mã." icon={<FileCheck2 size={18} />} columns={[{ key: 'code', label: 'Số hóa đơn' }, { key: 'direction', label: 'Loại' }, { key: 'counterparty', label: 'Đối tượng' }, { key: 'date', label: 'Ngày lập', format: 'date' }, { key: 'total', label: 'Tổng tiền', format: 'money' }, { key: 'status', label: 'Trạng thái', format: 'status' }, { key: 'mockTaxCode', label: 'Mã mô phỏng' }, { key: 'attachmentName', label: 'Tệp đính kèm' }]} fields={[{ name: 'code', label: 'Số hóa đơn', required: true }, { name: 'direction', label: 'Chiều hóa đơn', type: 'select', required: true, options: [{ value: 'OUTPUT', label: 'Đầu ra' }, { value: 'INPUT', label: 'Đầu vào' }] }, { name: 'invoiceType', label: 'Loại hóa đơn', placeholder: 'Bán hàng / GTGT / mua hàng' }, { name: 'counterparty', label: 'Khách hàng / nhà cung cấp', required: true }, { name: 'taxCode', label: 'Mã số thuế' }, { name: 'date', label: 'Ngày lập', type: 'date', required: true }, { name: 'subtotal', label: 'Tiền hàng (₫)', type: 'number', min: 0 }, { name: 'taxAmount', label: 'Tiền thuế (₫)', type: 'number', min: 0 }, { name: 'total', label: 'Tổng tiền (₫)', type: 'number', required: true, min: 0 }, { name: 'status', label: 'Trạng thái', type: 'select', options: [{ value: 'REVIEW_REQUIRED', label: 'Chờ rà soát' }, { value: 'SAVED', label: 'Đã lưu' }] }, { name: 'attachmentName', label: 'Tải hóa đơn/chứng từ (PDF hoặc ảnh)', type: 'file', wide: true }]} actions={(row) => row.direction === 'OUTPUT' && row.status !== 'DEMO_CODE_ISSUED' ? [{ label: 'Mô phỏng xin mã', action: 'simulate-code', variant: 'primary' }] : []} rowExtra={(row) => row.odooUrl ? <a href={row.odooUrl} target="_blank" rel="noreferrer" className="rounded-lg px-2 py-1 text-xs font-medium text-brand-700 hover:bg-brand-50">Mở Invoicing ↗</a> : row.syncStatus === 'PENDING_ODOO' ? <span className="px-2 py-1 text-xs text-muted">Đang đồng bộ Odoo…</span> : null} />
    </>;
}
function InfoIcon() { return <span className="mt-0.5 rounded-lg bg-white p-1.5 text-blue-700"><FileClock size={16} /></span>; }

